(()=>{const host=window.location.hostname;const domains=new Set(["",host,`.${host}`]);const parts=host.split(".");if(parts.length>2)domains.add(`.${parts.slice(-2).join(".")}`);for(const cookie of document.cookie.split(";")){const name=cookie.trim().split("=")[0];if(name!=="organizr_cookie_consent_v1"&&!/^_ga(?:_|$)/.test(name)&&!["_gid","_gat","_gcl_au"].includes(name))continue;for(const domain of domains){document.cookie=`${name}=; path=/; max-age=0; SameSite=Lax${domain ? `;domain=${domain}` : ""}`;}}})();